"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7548],{67548:e=>{e.exports=JSON.parse('{"slug":"bessent-khe-lifen-peregovory-tramp-si","locale":"ru","title":"Бессент и Хэ Лифэн провели переговоры в Нью-Йорке за 4 дня до встречи Трампа и Си","description":"Министр финансов США Скотт Бессент в воскресенье встретился в Нью-Йорке с вице-премьером КНР Хэ Лифэном перед встречей Трампа и Си в четверг. На кону продление торгового перемирия двух крупнейших экономик, а для России это вопрос спроса на нефть.","blocks":[{"id":"b001","kind":"paragraph","text":"Бессент написал в X, что они с Хэ Лифэном \xabпродолжают обсуждение американо-китайских экономических и торговых отношений\xbb перед \xabисторической встречей\xbb Трампа и Си в Вашингтоне, и приложил протокольное фото на фоне флагов. Других подробностей он не привёл. Позже Бессент назвал переговоры успешными и сказал, что стороны сосредоточились на торговле и искусственном интеллекте. Синьхуа встречу подтвердило. Сама встреча президентов пройдёт в четверг, 24 сентября."},{"id":"b002","kind":"paragraph","text":"Повестка известна из превью: тарифы, конкуренция в ИИ, экспортный контроль над полупроводниками, возможное производство китайских электромобилей в США, а фоном Тайвань и Иран. С майской встречи лидеров отношения ухудшились: американские чиновники публично говорят, что Китай не выполняет условия годового торгового перемирия. Над встречей нависают китайские ограничения на экспорт критических минералов и редкоземельных металлов, которые уже вызвали перебои у американских и других производителей."},{"id":"b003","kind":"paragraph","text":"Само \xabторговое перемирие\xbb устроено просто. Год назад стороны договорились не поднимать друг другу тарифы и не вводить новые ограничения. Это пауза в ссоре с датой окончания: договорились не ругаться, а потом решать, продлевать паузу или нет. Срок подходит к концу, и в этом главная интрига четверга. Не в том, что там подпишут что-то большое, а в том, что могут не подписать ничего. Тогда перемирие просто заканчивается, и обе стороны снова свободны в тарифах."},{"id":"b004","kind":"paragraph","text":"Редкоземельные металлы в этом торге работают как рычаг. Они нужны для электроники, батарей и оружия, а экспорт из Китая ограничен. Это как если бы у автозавода был единственный поставщик одной детали: он диктует цену и сроки, а завод не может собрать машину без неё. Поэтому перебои чувствительнее тарифов: с тарифом деталь дорожает, без поставки её нет совсем."},{"id":"b005","kind":"paragraph","text":"Рынки пока ждут, а не ставят. Фьючерсы на американские индексы в понедельник чуть подросли, доллар держался в узком коридоре. Это состояние, когда никто не хочет угадывать исход. Чем закончится четверг, неизвестно, и оба лидера умеют до последнего показывать готовность и договориться, и хлопнуть дверью."},{"id":"b006","kind":"paragraph","text":"Для России прямого канала здесь нет: ни один пункт повестки не касается российского импорта или рубля. Канал длинный. Если США и Китай снова начнут поднимать тарифы, мировая торговля замедляется, а с ней спрос на нефть, а нефть это доходы бюджета и опора курса. Если договорятся, давление на нефть с этой стороны уходит. Оценки масштаба нет."},{"id":"b007","kind":"paragraph","text":"Для обычного человека это новость, по которой не стоит действовать, но стоит следить. Покупать валюту \xabна всякий случай перед саммитом\xbb значит платить банку спред за событие, которого ещё не было. Считать, что торговые войны больших стран России не касаются, тоже не выйдет: через цену нефти они доезжают до бюджета и курса, просто с задержкой в месяцы."}],"sources":[{"label":"https://www.interfax.ru/world/1117310","url":"https://www.interfax.ru/world/1117310"},{"label":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html","url":"https://finance.yahoo.com/economy/policy/articles/trump-xi-showdown-casts-shadow-200000957.html"},{"label":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video","url":"https://www.bloomberg.com/news/videos/2026-09-21/trump-xi-to-meet-amidst-friction-on-wars-tech-trade-video"},{"label":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20","url":"https://www.reuters.com/business/finance/us-treasurys-bessent-chinas-he-launch-talks-on-ai-trade-critical-minerals-2026-09-20"},{"label":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap","url":"https://www.bloomberg.com/news/articles/2026-09-20/us-stock-futures-up-ahead-of-talks-dollar-steady-markets-wrap"}],"sourceBodySha256":"c1bc79749a4e70a8e26a07aaaf0de06d665d61f9e8ea4735408da5f270991985"}')}}]);